{
  "trigger": "The customer reports a problem with their router, internet connection, or Wi-Fi at home.",
  "steps": [
    {
      "type": "say",
      "message": "Let's check your router together. It'll take a minute."
    },
    {
      "type": "ask",
      "instruction": "Ask the customer what colour the power light on their router is: green, red, or off entirely."
    },
    {
      "type": "branch",
      "branches": [
        {
          "condition": {
            "type": "llm",
            "condition": "The customer says the power light is off, or there is no light at all."
          },
          "steps": [
            {
              "type": "tell",
              "instruction": "Explain that this points to a power problem, not a network one. Ask them to check the power cable at both ends and try a different wall socket."
            }
          ]
        },
        {
          "condition": {
            "type": "llm",
            "condition": "The customer says the power light is red, orange, or blinking."
          },
          "steps": [
            {
              "type": "tell",
              "instruction": "Explain that a red or blinking light means the router has power but no line signal. Ask them to unplug it for 30 seconds and plug it back in."
            }
          ]
        }
      ],
      "fallback": [
        {
          "type": "tell",
          "instruction": "Explain that a steady green light means the router itself is healthy, so the problem is likely with a single device or the Wi-Fi signal rather than the line."
        }
      ]
    },
    {
      "type": "ask",
      "instruction": "Ask whether that resolved the problem."
    }
  ]
}
